setcpm(84/4)

// Two brass choirs face each other across the church, one at each ear, as in the galleries of St Mark's
// They answer each other bar by bar, then join for the last four bars
const galleryA = "<1 0 1 0 1 1 1 1>"
const galleryB = "<0 1 0 1 1 1 1 1>"

// One four-bar canzona: C, F, G | Am, F, G | C, F, G | F, G, C
const canzona = note("<[[c4,e4,g4]@3 [c4,e4,g4] [f4,a4,c5]@2 [g4,b4,d5]@2] [[a3,c4,e4]@2 [f3,a3,c4]@2 [g3,b3,d4]@4] [[c4,e4,g4]@2 [e4,g4,c5]@2 [f4,a4,c5]@2 [g4,b4,d5]@2] [[f4,a4,c5]@2 [g4,b4,d5]@2 [e4,g4,c5]@4]>")

// The left gallery plays it bright, the right gallery an octave lower
left: canzona.mask(galleryA)
  .s("sawtooth").unison(2).detune(.1).lpf(1600).lpenv(1.5).lpattack(.05)
  .attack(.04).sustain(.7).release(.3).azimuth(-70).distance(4).space("church").gain(.18)
right: canzona.add(-12).mask(galleryB)
  .s("sawtooth").unison(2).detune(.1).lpf(1200).lpenv(1.5).lpattack(.05)
  .attack(.04).sustain(.7).release(.3).azimuth(70).distance(4).space("church").gain(.2)

// The organ pedal holds the centre, and timpani join for the tutti
pedal: note("<[c2@3 c2 f2@2 g2@2] [a1@2 f1@2 g1@4] [c2@4 f2@2 g2@2] [f2@2 g2@2 c2@4]>")
  .s("sawtooth").timbre("organ").lpf(500).attack(.1).sustain(.8).release(.5).space("church").gain(.22)
timpani: s("lt ~ lt ~").mask("<0 0 0 0 1 1 1 1>").speed(.7).lpf(800).room(.6).gain(.4)

setcpm(72/4)

// One theme, three entries a bar apart, each from its own place around your head
// Every strong beat of the theme lands on D, F# or A, so the entries fit over the pedal
const theme = n("<[0 2 4 2] [4 5 4 2] [7 6 7 4] [2@2 1 0]>").scale("D:major")
const bowed = (x, bright = 2600) => x.s("sawtooth").vib(5.5).vibdepth(.1).attack(.04).sustain(.6).release(.25).lpf(bright)

// First violin ahead-left, second violin ahead-right, viola behind you
first: theme.transpose(12).bowed(3200).azimuth(-60).distance(2).room(.4).gain(.2)
second: theme.late(1).bowed().azimuth(60).distance(2).room(.4).gain(.18)
third: theme.late(2).transpose(-12).bowed(1600).azimuth(180).distance(3).room(.4).gain(.18)

// The cello holds a D pedal in front of you, and a harpsichord marks the off-beats
cello: note("d2 a1").s("sawtooth").lpf(600).attack(.05).sustain(.6).release(.3).room(.4).gain(.26)
harpsichord: note("[d4,f#4,a4]").struct("~ x ~ x").s("square").pw(.15)
  .decay(.15).sustain(0).lpf(3000).gain(.08)

setcpm(60/4)

// Left hand: broken chords through Eb, Cm, Ab and Bb
left: note("<[eb2 bb2 g3 bb2 eb3 bb2 g3 bb2] [c2 g2 eb3 g2 c3 g2 eb3 g2] [ab1 eb2 c3 eb2 ab2 eb2 c3 eb2] [bb1 f2 d3 f2 bb2 f2 d3 f2]>")
  .s("triangle").timbre("soft").attack(.005).decay(.9).sustain(.1).release(1.2)
  .lpf(1800).room(.5).gain(.3)

// Right hand: the song, always in the centre of your head
right: note("<[g4@3 f4 eb4@2 f4 g4] [eb5@4 d5@2 c5 bb4] [c5@3 bb4 ab4@2 g4 f4] [f4@2 g4 ab4 g4@4]>")
  .s("sine").fm(.8).fmh(2).attack(.01).decay(1.4).sustain(.2).release(1.5)
  .room(.6).gain(.38)

// The strings step through the interaural phase, two bars at a time
// 0 degrees: centred. 90: looser. 180: diffuse and all around, and nearly gone in mono
pad: note("<[eb3,g3,bb3] [c3,eb3,g3] [ab2,c3,eb3] [bb2,d3,f3]>").s("sawtooth").unison(2).detune(.1)
  .iphase("<0 0 90 90 180 180 90 90>").lpf(1000).attack(1).sustain(1).release(2).gain(.1)

// Rain outside: unrelated noise in each ear, wide and enveloping
rain: s("pink").slow(8).icorr(.15).hpf(800).lpf(4000).gain(.03)

setcpm(60/4)

// The melody falls from f#5 and the countermelody rises from d4, but the two sections swap on every note
// Each ear alone hears a jagged line; many listeners hear a high line and a low line that meet and part
firsts: note("f#5 e4 d5 g4 b4 b4 g4 d5").s("sawtooth").vib(5).vibdepth(.1).lpf(2800)
  .attack(.04).sustain(.7).release(.2).pan(0).room(.4).gain(.2)
seconds: note("d4 e5 f#4 c#5 a4 a4 c#5 f#4").s("sawtooth").vib(5).vibdepth(.1).lpf(2800)
  .attack(.04).sustain(.7).release(.2).pan(1).room(.4).gain(.2)

// The cellos and basses, the same in both ears
cello: note("d2 a1").s("sawtooth").vib(4.5).vibdepth(.08).lpf(600)
  .attack(.2).sustain(.7).release(.6).room(.5).gain(.26)

// Soft horns hold the harmony in the centre
horns: note("<[d3,a3] [d3,f#3]>").s("triangle").timbre("soft")
  .attack(.8).sustain(.8).release(1.5).room(.6).gain(.12)

setcpm(48/4)

// earsh raises the right ear and lowers the left by half the value each
// 2 cents beats slowly; 6 and 12 shimmer like a larger section; 30 blooms into a chorus
strings: note("<[bb2,f3,db4,f4] [gb2,db3,bb3,eb4] [ab2,eb3,c4,eb4] [f2,c3,a3,eb4]>").slow(2)
  .s("sawtooth").unison(2).detune(.1).earsh("<2 2 6 6 12 12 30 30>")
  .lpf(1300).attack(2).sustain(1).release(3).room(.7).size(.9).gain(.14)

// A solo violin, the same in both ears, singing over the chords: Bbm, Gb, Ab, F7
solo: note("<[f4@3 gb4] [ab4@2 gb4 f4] [eb4@4] [db4 eb4 f4@2] [eb4@3 f4] [ab4@2 gb4 eb4] [f4@4] [a4@2 f4@2]>")
  .s("sawtooth").mono(1).glide(.1).vib(5).vibdepth(.15).lpf(2600)
  .attack(.3).sustain(.7).release(1).room(.6).gain(.18)

// The cellos hold the roots, centred
cello: note("<bb1 gb1 ab1 f1>").slow(2).s("sawtooth").vib(4.5).vibdepth(.08)
  .lpf(600).attack(1).sustain(.8).release(2).room(.5).gain(.22)

setcpm(56/4)

// irate turns the phase between the ears, in turns per second, like a slowly rotating speaker
// All rates stay below 3 Hz, so no pulse warning is needed
organ: note("<[c3,e3,g3,c4] [a2,c3,e3,a3] [f2,a2,c3,f3] [g2,b2,d3,g3]>")
  .s("sawtooth").timbre("organ").irate("<.25 .25 .5 .5 1 1 2 2>")
  .lpf(1200).attack(.4).sustain(.9).release(1).space("church").gain(.16)

// The hymn on a reed stop, the same in both ears: C, Am, F, G
cantus: note("<[e4@2 d4 c4] [c4@2 e4 a4] [a4@2 g4 f4] [d4@2 b3 d4]>")
  .s("sawtooth").timbre("reed").lpf(1800).attack(.1).sustain(.7).release(.6)
  .space("church").gain(.2)

// The pedal walks the roots, centred
pedal: note("<c2 a1 f1 g1>").s("sawtooth").timbre("organ").lpf(450)
  .attack(.2).sustain(.8).release(1).space("church").gain(.24)

// A bell at the start of each phrase
bell: note("<g4 ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(3).sustain(0).release(3).space("church").gain(.1)

setcpm(66/4)

// First violin: a low-pass on each ear alone, sweeping in opposite directions every eight bars
// The level stays put; only the brightness wanders between the ears
violin: n("0 2 4 7 4 2 0 2").add("<0 0 3 3 4 4 0 0>").scale("A:minor").transpose(12)
  .s("sawtooth").vib(5.5).vibdepth(.1)
  .lcutoff(saw.range(500, 4000).slow(8)).rcutoff(isaw.range(500, 4000).slow(8))
  .attack(.02).decay(.2).sustain(.4).release(.2).room(.4).gain(.18)

// Second violin plucks the chord tones
pizz: n("[0 ~ 4 ~]*2").add("<0 0 3 3 4 4 0 0>").scale("A:minor")
  .s("triangle").timbre("bright").decay(.15).sustain(0).release(.2).room(.4).gain(.18)

// A high-pass on the right ear only: the viola sounds fuller on the left
viola: note("<[c4,e4] [c4,e4] [d4,f4] [d4,f4] [e4,g4] [e4,b4] [c4,e4] [c4,e4]>")
  .s("sawtooth").rhcutoff(1000).lpf(1600).attack(.3).sustain(.8).release(.8).room(.4).gain(.12)

// The cello on the roots, the same in both ears
cello: note("<a2 a2 d2 d2 e2 e2 a2 a2>").s("sawtooth").vib(4.5).vibdepth(.08)
  .lpf(700).attack(.2).sustain(.7).release(.8).room(.4).gain(.24)

setcpm(60/3)

// One cycle is a bar of 3/4
// A 2 Hz binaural drone on an open fifth: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("[f1,c2]").slow(8).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// The cradle song on a music box, floating above your head: F, F, C, C, Bb, C7, C, F
musicbox: note("<[a4 a4 c5] [a4@2 c5] [g4 f4 g4] [e4@2 c4] [d4 e4 f4] [g4@2 bb4] [a4 g4 e4] [f4@3]>")
  .s("sine").fm(2).fmh(4).attack(.002).decay(1).sustain(0).release(1.5)
  .elevation(40).distance(2).room(.6).size(.85).gain(.2)

// A soft root on each downbeat, and someone humming along
bass: note("<f2 f2 c2 c2 bb1 c2 c2 f2>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.2)
hum: note("<f3 f3 e3 e3 d3 e3 e3 f3>").s("hum").attack(.6).release(1.5).gain(.1)

// Crickets far away
crickets: s("insect").slow(4).distance(8).gain(.06)
